<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class EmployeeController extends Controller{
 public function index(Request $r){$q=DB::table('employees as e')->leftJoin('employee_employments as em',fn($j)=>$j->on('em.employee_id','=','e.id')->where('em.status','=','active'))->leftJoin('staff_positions as p','p.id','=','em.position_id')->leftJoin('academic_departments as d','d.id','=','em.academic_department_id')->select('e.*','p.name as position_name','d.name as department_name','em.employment_type','em.rate');if($r->filled('q')){$s='%'.$r->q.'%';$q->where(fn($x)=>$x->where('e.last_name','like',$s)->orWhere('e.first_name','like',$s));}if($r->status==='active')$q->where('e.active',1);if($r->status==='archive')$q->where('e.active',0);return view('admin.employees.index',['rows'=>$q->orderBy('e.last_name')->get()]);}
 public function create(){return view('admin.employees.form',$this->form(null));}
 public function store(Request $r){$d=$this->person($r);$id=DB::table('employees')->insertGetId($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('admin.employees.edit',$id)->with('success','Сотрудник создан');}
 public function edit($id){$e=DB::table('employees')->find($id);abort_if(!$e,404);return view('admin.employees.form',$this->form($e));}
 public function update(Request $r,$id){abort_unless(DB::table('employees')->where('id',$id)->exists(),404);DB::table('employees')->where('id',$id)->update($this->person($r)+['updated_at'=>now()]);return back()->with('success','Карточка сотрудника сохранена');}
 public function education(Request $r,$id){abort_unless(DB::table('employees')->where('id',$id)->exists(),404);$d=$r->validate(['level'=>'required|string|max:100','institution'=>'required|string|max:255','specialty'=>'nullable|string|max:255','qualification'=>'nullable|string|max:255','document_series'=>'nullable|string|max:50','document_number'=>'nullable|string|max:100','issued_on'=>'nullable|date','graduation_year'=>'nullable|integer|min:1940|max:2100']);DB::table('employee_educations')->insert($d+['employee_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Образование добавлено');}
 public function training(Request $r,$id){abort_unless(DB::table('employees')->where('id',$id)->exists(),404);$d=$r->validate(['kind'=>'required|in:qualification,retraining,internship,seminar','program'=>'required|string|max:500','provider'=>'nullable|string|max:255','hours'=>'nullable|integer|min:1|max:10000','starts_on'=>'nullable|date','ends_on'=>'nullable|date|after_or_equal:starts_on','document_type'=>'nullable|string|max:100','document_number'=>'nullable|string|max:100','document_date'=>'nullable|date','valid_until'=>'nullable|date']);DB::table('employee_trainings')->insert($d+['employee_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Обучение добавлено');}
 public function attestation(Request $r,$id){abort_unless(DB::table('employees')->where('id',$id)->exists(),404);$d=$r->validate(['area'=>'required|in:pedagogical,administrative,master','planned_on'=>'nullable|date','held_on'=>'nullable|date','status'=>'required|in:planned,completed,cancelled','result'=>'nullable|string|max:100','category'=>'nullable|string|max:150','category_valid_until'=>'nullable|date','protocol_number'=>'nullable|string|max:100','commission'=>'nullable|string|max:5000','next_attestation_on'=>'nullable|date','note'=>'nullable|string|max:5000']);DB::table('employee_attestations')->insert($d+['employee_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Аттестация добавлена');}
 public function position(Request $r){$d=$r->validate(['code'=>'nullable|string|max:50|unique:staff_positions,code','name'=>'required|string|max:255','pedagogical'=>'nullable|boolean']);DB::table('staff_positions')->insert(['code'=>$d['code']??null,'name'=>$d['name'],'pedagogical'=>$r->boolean('pedagogical'),'active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Должность добавлена');}
 public function order(Request $r){$d=$r->validate(['employee_id'=>'required|exists:employees,id','number'=>'required|string|max:100','order_date'=>'required|date','type'=>'required|in:hire,transfer,dismissal','effective_on'=>'required|date','position_id'=>'nullable|exists:staff_positions,id','academic_department_id'=>'nullable|exists:academic_departments,id','employment_type'=>'nullable|in:staff,internal_part_time,external_part_time,civil_contract','rate'=>'nullable|numeric|min:0.01|max:5','basis'=>'nullable|string|max:5000']);DB::transaction(function()use($r,$d){$emp=null;if($d['type']==='hire'){abort_if(empty($d['position_id']),422,'Для приёма укажите должность');$emp=DB::table('employee_employments')->insertGetId(['employee_id'=>$d['employee_id'],'position_id'=>$d['position_id'],'academic_department_id'=>$d['academic_department_id']??null,'employment_type'=>$d['employment_type']??'staff','rate'=>$d['rate']??1,'starts_on'=>$d['effective_on'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);}elseif($d['type']==='transfer'){$old=DB::table('employee_employments')->where(['employee_id'=>$d['employee_id'],'status'=>'active'])->orderByDesc('starts_on')->first();abort_if(!$old,422,'Нет активного места работы');DB::table('employee_employments')->where('id',$old->id)->update(['status'=>'closed','ends_on'=>$d['effective_on'],'updated_at'=>now()]);$emp=DB::table('employee_employments')->insertGetId(['employee_id'=>$d['employee_id'],'position_id'=>$d['position_id']??$old->position_id,'academic_department_id'=>$d['academic_department_id']??$old->academic_department_id,'employment_type'=>$d['employment_type']??$old->employment_type,'rate'=>$d['rate']??$old->rate,'starts_on'=>$d['effective_on'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);}else{DB::table('employee_employments')->where(['employee_id'=>$d['employee_id'],'status'=>'active'])->update(['status'=>'closed','ends_on'=>$d['effective_on'],'updated_at'=>now()]);DB::table('employees')->where('id',$d['employee_id'])->update(['active'=>0,'updated_at'=>now()]);}$order=['employee_id'=>$d['employee_id'],'number'=>$d['number'],'order_date'=>$d['order_date'],'type'=>$d['type'],'effective_on'=>$d['effective_on'],'employment_id'=>$emp,'basis'=>$d['basis']??null,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()];DB::table('personnel_orders')->insert($order);});return back()->with('success','Кадровый приказ проведён');}
 private function person(Request $r){return $r->validate(['teacher_id'=>'nullable|exists:teachers,id|unique:employees,teacher_id,'.($r->route('employee')??'NULL').',id','last_name'=>'required|string|max:100','first_name'=>'required|string|max:100','middle_name'=>'nullable|string|max:100','birth_date'=>'nullable|date','phone'=>'nullable|string|max:100','email'=>'nullable|email|max:255','snils'=>'nullable|string|max:50','inn'=>'nullable|string|max:50']);}
 private function form($e){$id=$e->id??0;return ['employee'=>$e,'teachers'=>DB::table('teachers')->where('active',1)->orderBy('last_name')->get(),'positions'=>DB::table('staff_positions')->where('active',1)->orderBy('name')->get(),'departments'=>DB::table('academic_departments')->where('active',1)->orderBy('name')->get(),'employments'=>DB::table('employee_employments as em')->join('staff_positions as p','p.id','=','em.position_id')->leftJoin('academic_departments as d','d.id','=','em.academic_department_id')->where('em.employee_id',$id)->select('em.*','p.name as position_name','d.name as department_name')->orderByDesc('em.starts_on')->get(),'orders'=>DB::table('personnel_orders')->where('employee_id',$id)->orderByDesc('order_date')->get(),'educations'=>DB::table('employee_educations')->where('employee_id',$id)->orderByDesc('graduation_year')->get(),'trainings'=>DB::table('employee_trainings')->where('employee_id',$id)->orderByDesc('ends_on')->get(),'attestations'=>DB::table('employee_attestations')->where('employee_id',$id)->orderByDesc('planned_on')->get()];}
}